text:
{
  "design": {
    "theme": "studio",
    "picture_style": "illustration"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall familiar French greetings and numbers",
      "look_at": {"kind": "picture", "shows": "A family ready to be introduced"},
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Share the approved learning objectives",
      "look_at": {"kind": "none", "shows": null},
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach family nouns and mon/ma",
      "look_at": {"kind": "diagram", "shows": "Four family nouns with English meanings and their possessives"},
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Model introducing and naming family members",
      "look_at": {"kind": "picture", "shows": "A father and a mother beside their introductions"},
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Practise near-identical introductions",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Teach age numbers and correct a/est confusion",
      "look_at": {"kind": "diagram", "shows": "French numbers from one to twenty"},
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Practise age sentences and contrast description",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Check age grammar before moving on",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Model linked sentences and adjective agreement",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [3]
    },
    {
      "slide": 10,
      "does": "Apply the model to new family profiles",
      "look_at": {"kind": "none", "shows": null},
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Ma famille",
    "lead": "My family\nSay hello in French.\nSay any French numbers you know from 1 to 10.",
    "picture": {
      "shows": "Two parents and two teenage siblings together at home",
      "must_see": ["two adult parents", "two teenage siblings"],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Les membres de ma famille",
      "lead": "Voici… = Here is…",
      "points": [
        {"label": "mon", "text": "my + a masculine noun"},
        {"label": "ma", "text": "my + a feminine noun"}
      ],
      "figure": {
        "kind": "table",
        "shows": "Family nouns paired with their possessives and English meanings",
        "alt": "Mon père means my father; ma mère means my mother; mon frère means my brother; ma sœur means my sister.",
        "title": null,
        "header": ["Français", "English"],
        "rows": [
          ["mon père", "father"],
          ["ma mère", "mother"],
          ["mon frère", "brother"],
          ["ma sœur", "sister"]
        ]
      }
    },
    {
      "template": "compare",
      "heading": "Présenter quelqu’un — introduce someone",
      "columns": [
        {
          "label": "Mon père",
          "text": "Voici mon père. Il s’appelle Marc.",
          "picture": {
            "shows": "An adult father smiling",
            "must_see": ["adult man", "friendly smile"],
            "subject": "generic"
          }
        },
        {
          "label": "Ma mère",
          "text": "Voici ma mère. Elle s’appelle Nadia.",
          "picture": {
            "shows": "An adult mother smiling",
            "must_see": ["adult woman", "friendly smile"],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "practice",
      "heading": "À toi — your turn",
      "questions": [
        "Introduce your brother, Hugo. Write two sentences using Voici… and Il s’appelle…",
        "Introduce your sister, Léa. Write two sentences using Voici… and Elle s’appelle…",
        "Complete: Voici ___ mère. ___ s’appelle Sara. Explain your choice of mon or ma."
      ],
      "instruction": "Write in French. Mon = my + masculine noun; ma = my + feminine noun.",
      "picture": null
    },
    {
      "template": "visual-text",
      "heading": "L’âge — age",
      "lead": "Il a treize ans. = He is thirteen years old.",
      "points": [
        {"label": "Age: a", "text": "Elle a treize ans. = She is thirteen."},
        {"label": "Description: est", "text": "Il est gentil. = He is kind. Not: Il est treize ans."}
      ],
      "figure": {
        "kind": "table",
        "shows": "A reference bank of the French numbers one to twenty",
        "alt": "French numbers from one to twenty, arranged in two pairs of columns.",
        "title": null,
        "header": ["Nombre", "Français", "Nombre", "Français"],
        "rows": [
          ["1", "un", "11", "onze"],
          ["2", "deux", "12", "douze"],
          ["3", "trois", "13", "treize"],
          ["4", "quatre", "14", "quatorze"],
          ["5", "cinq", "15", "quinze"],
          ["6", "six", "16", "seize"]
        ]
      }
    },
    {
      "template": "practice",
      "heading": "Écris l’âge — write the age",
      "questions": [
        "Your brother is 14 (quatorze). Write his age using Il…",
        "Your sister is 17 (dix-sept). Write her age using Elle…",
        "Complete with a or est: Il ___ vingt ans. Il ___ gentil. Explain the difference."
      ],
      "instruction": "Use a… ans for age. Number bank: 7 sept; 8 huit; 9 neuf; 10 dix; 17 dix-sept; 18 dix-huit; 19 dix-neuf; 20 vingt.",
      "picture": null
    },
    {
      "template": "hinge",
      "heading": "Choisis — choose",
      "stem": "Which sentence means ‘She is eighteen years old’?",
      "options": [
        "Elle est dix-huit ans.",
        "Elle a dix-huit ans.",
        "Il a dix-huit ans.",
        "Elle a dix-huit."
      ],
      "correct": 2
    },
    {
      "template": "explain",
      "heading": "Lier les phrases — link sentences",
      "lead": "Voici ma sœur. Elle s’appelle Léa. Elle a quinze ans et elle est gentille.",
      "points": [
        "Kind: il est gentil / elle est gentille.",
        "Funny: il est amusant / elle est amusante.",
        "Et = and. Add -le to gentil; add -e to amusant with elle."
      ]
    },
    {
      "template": "practice",
      "heading": "Décris ta famille — describe your family",
      "questions": [
        "Write three sentences: sister; name Inès; age 16 (seize); kind. Link age and personality with et.",
        "Write three or four linked sentences: brother; name Sami; age 19 (dix-neuf); funny.",
        "Stretch: introduce both siblings in four sentences. Include both names, ages and personalities."
      ],
      "instruction": "Use Voici…, Il/Elle s’appelle…, Il/Elle a… ans and Il/Elle est… . Kind: gentil/gentille. Funny: amusant/amusante. Et = and.",
      "picture": null
    }
  ]
}
